FUNCTION_BLOCK FB_KomutGecidi
VAR_IN_OUT
    udiSiraBaslangic : UDINT;
    diKomutDegeri : DINT;
    udiSiraBitis : UDINT;
END_VAR

VAR_OUTPUT
    udiOnaySirasi : UDINT := 0;
    diYanitDegeri : DINT := 0;
    uiSonuc : UINT := 0;
    udiIslenenKomutSayisi : UDINT := 0;
END_VAR

VAR
    udiIlkBaslangic : UDINT;
    udiIkinciBaslangic : UDINT;
    udiBitisKopyasi : UDINT;
    diDegerKopyasi : DINT;

    udiSonKabulSirasi : UDINT := 0;
    diSonKabulDegeri : DINT := 0;
END_VAR

FUNCTION_BLOCK FB_KomutGecidi
VAR_IN_OUT
    udiSiraBaslangic : UDINT;
    diKomutDegeri : DINT;
    udiSiraBitis : UDINT;
END_VAR

VAR_OUTPUT
    udiOnaySirasi : UDINT := 0;
    diYanitDegeri : DINT := 0;
    uiSonuc : UINT := 0;
    udiIslenenKomutSayisi : UDINT := 0;
END_VAR

VAR
    udiIlkBaslangic : UDINT;
    udiIkinciBaslangic : UDINT;
    udiBitisKopyasi : UDINT;
    diDegerKopyasi : DINT;

    udiSonKabulSirasi : UDINT := 0;
    diSonKabulDegeri : DINT := 0;
END_VAR

FUNCTION_BLOCK FB_KomutGecidi
VAR_IN_OUT
    udiSiraBaslangic : UDINT;
    diKomutDegeri : DINT;
    udiSiraBitis : UDINT;
END_VAR

VAR_OUTPUT
    udiOnaySirasi : UDINT := 0;
    diYanitDegeri : DINT := 0;
    uiSonuc : UINT := 0;
    udiIslenenKomutSayisi : UDINT := 0;
END_VAR

VAR
    udiIlkBaslangic : UDINT;
    udiIkinciBaslangic : UDINT;
    udiBitisKopyasi : UDINT;
    diDegerKopyasi : DINT;

    udiSonKabulSirasi : UDINT := 0;
    diSonKabulDegeri : DINT := 0;
END_VAR

ST.xhtml:
// Komut verilerini yerel kopyaya al.
// Kopyalama sonunda baslangic numarasini tekrar kontrol et.
udiIlkBaslangic := udiSiraBaslangic;
diDegerKopyasi := diKomutDegeri;
udiBitisKopyasi := udiSiraBitis;
udiIkinciBaslangic := udiSiraBaslangic;

// 0: komut yok.
// Numaralar farkliysa yazim henuz tamamlanmamis olabilir.
// Mevcut cevabi koru ve sonraki PLC cevrimini bekle.
IF (udiIlkBaslangic = 0)
    OR (udiIlkBaslangic <> udiIkinciBaslangic)
    OR (udiIlkBaslangic <> udiBitisKopyasi) THEN
    RETURN;
END_IF;

// Son kabul edilen komut tekrar gonderilmis.
IF udiIlkBaslangic = udiSonKabulSirasi THEN

    IF diDegerKopyasi = diSonKabulDegeri THEN
        // Ayni komut: onceki cevabi tekrar sun, sayaci artirma.
        diYanitDegeri := diSonKabulDegeri;
        uiSonuc := 1;
    ELSE
        // Ayni sira numarasiyla farkli veri: gecersiz.
        uiSonuc := 2;
    END_IF;

    udiOnaySirasi := udiIlkBaslangic;
    RETURN;
END_IF;

// Sira numarasinin tasmasina izin verme.
IF udiSonKabulSirasi = UDINT#4294967295 THEN
    uiSonuc := 2;
    udiOnaySirasi := udiIlkBaslangic;
    RETURN;
END_IF;

// Yalniz siradaki numarayi kabul et: 1, 2, 3...
IF udiIlkBaslangic <> (udiSonKabulSirasi + 1) THEN
    uiSonuc := 2;
    udiOnaySirasi := udiIlkBaslangic;
    RETURN;
END_IF;

// Yeni ve tamamlanmis komutu bir kez isle.
udiSonKabulSirasi := udiIlkBaslangic;
diSonKabulDegeri := diDegerKopyasi;

diYanitDegeri := diDegerKopyasi;
udiIslenenKomutSayisi := udiIslenenKomutSayisi + 1;
uiSonuc := 1;
udiOnaySirasi := udiIlkBaslangic;

