PROGRAM PRG_Ana
VAR
	fbKonveyorIzin : FB_KonveyorIzin;
    udiCalismaSayaci : UDINT := 0;
    fbKomutGecidi : FB_KomutGecidi;
	fbMakineModeli : FB_MakineModeli;
	fbCalismaYonetimi : FB_CalismaYonetimi;
	fbGirisKontrol : FB_GirisKontrol;
    xSecilenIleri : BOOL;
    xSecilenGeri  : BOOL;
END_VAR

ST.xhtml:
// Calisma sayaci
udiCalismaSayaci := udiCalismaSayaci + 1;
GVL_Haberlesme.Durum_CalismaSayaci := udiCalismaSayaci;

// Komut kontrolu
fbKomutGecidi(
    udiSiraBaslangic := GVL_Haberlesme.Komut_SiraBaslangic,
    diKomutDegeri := GVL_Haberlesme.Komut_Deger,
    udiSiraBitis := GVL_Haberlesme.Komut_SiraBitis
);

// Sonucu disaridan okunacak alanlara aktar
GVL_Haberlesme.Durum_YanitDegeri := fbKomutGecidi.diYanitDegeri;
GVL_Haberlesme.Durum_KomutSonucu := fbKomutGecidi.uiSonuc;
GVL_Haberlesme.Durum_IslenenKomutSayisi := fbKomutGecidi.udiIslenenKomutSayisi;
GVL_Haberlesme.Durum_OnaySirasi := fbKomutGecidi.udiOnaySirasi;

fbCalismaYonetimi(
    xBaslat := GVL_Deneme.xBaslat,
    xDurdur := GVL_Deneme.xDurdur,
    xSifirla := GVL_Deneme.xSifirla,
    xGirislerGecerli := GVL_GirisCikis.stGiris.xGirislerGecerli,
    xYonCakismasi := GVL_Deneme.xIleri AND GVL_Deneme.xGeri,
    xIsteklerBos := NOT (GVL_Deneme.xIleri OR GVL_Deneme.xGeri)
);
fbGirisKontrol(
    xOtomatikIstegi := GVL_Deneme.xOtomatikIstegi,
    xCalismaIzni := fbCalismaYonetimi.xCalismaIzni,
    xGirislerGecerli := GVL_GirisCikis.stGiris.xGirislerGecerli,
    xGiris := GVL_GirisCikis.stGiris.xGiris,
    xTanima := GVL_GirisCikis.stGiris.xTanima,
    xYolBos := GVL_GirisCikis.stGiris.xYolBos,
    xIsteklerBos := NOT (GVL_Deneme.xIleri OR GVL_Deneme.xGeri),
    xSifirla := GVL_Deneme.xSifirla,
    tSinir := GVL_Ayarlar.tGirisSiniri
);

IF fbGirisKontrol.xOtomatikEtkin THEN
    xSecilenIleri := fbGirisKontrol.xOtomatikIleri;
    xSecilenGeri := FALSE;
ELSE
    xSecilenIleri := GVL_Deneme.xIleri;
    xSecilenGeri := GVL_Deneme.xGeri;
END_IF;

fbKonveyorIzin(
    xIzin := fbCalismaYonetimi.xCalismaIzni
             AND GVL_GirisCikis.stGiris.xGirislerGecerli,
    xIleriIstegi := xSecilenIleri,
    xGeriIstegi := xSecilenGeri
);

GVL_GirisCikis.stCikis.xKonveyorIleri := fbKonveyorIzin.xIleri;
GVL_GirisCikis.stCikis.xKonveyorGeri := fbKonveyorIzin.xGeri;

fbMakineModeli(
    stKomut := GVL_GirisCikis.stCikis,
    xSikisma := GVL_Deneme.xSikisma,
	xAmbalajEkle := GVL_Deneme.xAmbalajEkle
    AND (NOT fbGirisKontrol.xOtomatikEtkin OR fbGirisKontrol.xYeniAmbalajHazir),
    xAmbalajAl := GVL_Deneme.xAmbalajAl
);
GVL_GirisCikis.stGiris := fbMakineModeli.stSensor;

