    xGirislerGecerli : BOOL;
    xGiris          : BOOL;
    xTanima         : BOOL;
    xYolBos         : BOOL;
    xIsteklerBos    : BOOL;
    xSifirla        : BOOL;
    tSinir          : TIME;
END_VAR
VAR_OUTPUT
    xOtomatikEtkin   : BOOL;
    xOtomatikIleri   : BOOL;
    xGirisHatasi     : BOOL;
    xYeniAmbalajHazir : BOOL;
    eGirisDurumu     : E_GirisDurumu := E_GirisDurumu.BEKLE;
    uiGirisDurumu    : UINT;
END_VAR
VAR
    fbGiris   : R_TRIG;
    fbSifirla : R_TRIG;
    fbSure    : TON;
    xKurulu   : BOOL;
END_VAR

FUNCTION_BLOCK FB_GirisKontrol
VAR_INPUT
    xOtomatikIstegi  : BOOL;
    xCalismaIzni     : BOOL;
    xGirislerGecerli : BOOL;
    xGiris          : BOOL;
    xTanima         : BOOL;
    xYolBos         : BOOL;
    xIsteklerBos    : BOOL;
    xSifirla        : BOOL;
    tSinir          : TIME;
END_VAR
VAR_OUTPUT
    xOtomatikEtkin   : BOOL;
    xOtomatikIleri   : BOOL;
    xGirisHatasi     : BOOL;
    xYeniAmbalajHazir : BOOL;
    eGirisDurumu     : E_GirisDurumu := E_GirisDurumu.BEKLE;
    uiGirisDurumu    : UINT;
END_VAR
VAR
    fbGiris   : R_TRIG;
    fbSifirla : R_TRIG;
    fbSure    : TON;
    xKurulu   : BOOL;
END_VAR

FUNCTION_BLOCK FB_GirisKontrol
VAR_INPUT
    xOtomatikIstegi  : BOOL;
    xCalismaIzni     : BOOL;
    xGirislerGecerli : BOOL;
    xGiris          : BOOL;
    xTanima         : BOOL;
    xYolBos         : BOOL;
    xIsteklerBos    : BOOL;
    xSifirla        : BOOL;
    tSinir          : TIME;
END_VAR
VAR_OUTPUT
    xOtomatikEtkin   : BOOL;
    xOtomatikIleri   : BOOL;
    xGirisHatasi     : BOOL;
    xYeniAmbalajHazir : BOOL;
    eGirisDurumu     : E_GirisDurumu := E_GirisDurumu.BEKLE;
    uiGirisDurumu    : UINT;
END_VAR
VAR
    fbGiris   : R_TRIG;
    fbSifirla : R_TRIG;
    fbSure    : TON;
    xKurulu   : BOOL;
END_VAR

ST.xhtml:
fbGiris(CLK := xGiris);
fbSifirla(CLK := xSifirla);

IF NOT xCalismaIzni AND xIsteklerBos THEN
    IF NOT xOtomatikIstegi THEN
        xOtomatikEtkin := FALSE;
    ELSIF xYolBos AND xGirislerGecerli
          AND eGirisDurumu <> E_GirisDurumu.HATA THEN
        xOtomatikEtkin := TRUE;
    END_IF;
END_IF;

fbSure(
    IN := xOtomatikEtkin AND xCalismaIzni AND xGirislerGecerli
          AND eGirisDurumu = E_GirisDurumu.ICERI_AL AND NOT xTanima,
    PT := tSinir
);

IF NOT xOtomatikEtkin THEN
    xKurulu := FALSE;
    IF eGirisDurumu <> E_GirisDurumu.HATA THEN
        eGirisDurumu := E_GirisDurumu.BEKLE;
    END_IF;
ELSIF NOT xGirislerGecerli THEN
    eGirisDurumu := E_GirisDurumu.HATA;
ELSE
    CASE eGirisDurumu OF
        E_GirisDurumu.BEKLE:
            IF NOT xCalismaIzni THEN
                xKurulu := FALSE;
            ELSIF xYolBos AND NOT xGiris AND NOT xTanima THEN
                xKurulu := TRUE;
            ELSIF xKurulu AND fbGiris.Q AND NOT xYolBos THEN
                xKurulu := FALSE;
                eGirisDurumu := E_GirisDurumu.ICERI_AL;
            ELSIF NOT xYolBos THEN
                eGirisDurumu := E_GirisDurumu.HATA;
            END_IF;

        E_GirisDurumu.ICERI_AL:
            IF xYolBos THEN
                eGirisDurumu := E_GirisDurumu.HATA;
            ELSIF xTanima THEN
                eGirisDurumu := E_GirisDurumu.TANIMA_BEKLE;
            ELSIF fbSure.Q THEN
                eGirisDurumu := E_GirisDurumu.HATA;
            END_IF;

        E_GirisDurumu.TANIMA_BEKLE:
            IF xYolBos OR NOT xTanima THEN
                eGirisDurumu := E_GirisDurumu.HATA;
            END_IF;

        E_GirisDurumu.HATA:
            xKurulu := FALSE;
        ELSE
            eGirisDurumu := E_GirisDurumu.HATA;
    END_CASE;
END_IF;

IF fbSifirla.Q AND NOT xCalismaIzni AND xYolBos AND xGirislerGecerli THEN
    eGirisDurumu := E_GirisDurumu.BEKLE;
    xKurulu := FALSE;
END_IF;

xGirisHatasi := eGirisDurumu = E_GirisDurumu.HATA;
xOtomatikIleri := xOtomatikEtkin AND xCalismaIzni AND xGirislerGecerli
                  AND eGirisDurumu = E_GirisDurumu.ICERI_AL
                  AND NOT xTanima AND NOT xYolBos;
xYeniAmbalajHazir := xOtomatikEtkin AND xCalismaIzni AND xGirislerGecerli
                    AND eGirisDurumu = E_GirisDurumu.BEKLE
                    AND xKurulu AND xYolBos;
uiGirisDurumu := TO_UINT(eGirisDurumu);

