FUNCTION F_RVMMaterial104 : UINT
VAR_INPUT
    metal : BOOL;
    mass : REAL;
    optics : REAL;
    length : REAL;
END_VAR

ST.xhtml:
F_RVMMaterial104 := 0;
IF (length >= 0.10) AND (length <= 0.30) THEN
    IF metal AND (mass >= 8.0) AND (mass <= 40.0) THEN
        F_RVMMaterial104 := 2;
    ELSIF NOT metal AND (optics > 0.55) THEN
        IF (mass >= 10.0) AND (mass <= 45.0) THEN F_RVMMaterial104 := 1;
        ELSIF (mass >= 100.0) AND (mass <= 400.0) THEN F_RVMMaterial104 := 3;
        END_IF;
    END_IF;
END_IF;

