    fbEkle : R_TRIG;
    fbAl : R_TRIG;
END_VAR

FUNCTION_BLOCK FB_MakineModeli
VAR_INPUT
    stKomut : ST_RvmCikislari;
    xSikisma : BOOL;
    xAmbalajEkle : BOOL;
    xAmbalajAl : BOOL;
END_VAR

VAR_OUTPUT
    rKonum : REAL := 0.0;
    xAmbalajVar : BOOL;
    xYonCakismasi : BOOL;
    stSensor : ST_RvmGirisleri;
END_VAR

VAR
    fbEkle : R_TRIG;
    fbAl : R_TRIG;
END_VAR

FUNCTION_BLOCK FB_MakineModeli
VAR_INPUT
    stKomut : ST_RvmCikislari;
    xSikisma : BOOL;
    xAmbalajEkle : BOOL;
    xAmbalajAl : BOOL;
END_VAR

VAR_OUTPUT
    rKonum : REAL := 0.0;
    xAmbalajVar : BOOL;
    xYonCakismasi : BOOL;
    stSensor : ST_RvmGirisleri;
END_VAR

VAR
    fbEkle : R_TRIG;
    fbAl : R_TRIG;
END_VAR

ST.xhtml:
fbEkle(CLK := xAmbalajEkle);
fbAl(CLK := xAmbalajAl);

// Iade noktasindaki ambalaji kullanici alir.
// Bos modele yeni ambalaj eklenebilir.
IF fbAl.Q AND xAmbalajVar
    AND (rKonum <= GVL_Ayarlar.rIadeSiniri) THEN

    xAmbalajVar := FALSE;

ELSIF fbEkle.Q AND NOT xAmbalajVar THEN
    xAmbalajVar := TRUE;
    rKonum := GVL_Ayarlar.rGirisKonumu;
END_IF;

// Hareket
xYonCakismasi :=
    stKomut.xKonveyorIleri AND stKomut.xKonveyorGeri;

IF xAmbalajVar AND NOT xSikisma AND NOT xYonCakismasi THEN
    IF stKomut.xKonveyorIleri THEN
        rKonum := MIN(
            GVL_Ayarlar.rYolSonu,
            rKonum + GVL_Ayarlar.rAdim
        );
    ELSIF stKomut.xKonveyorGeri THEN
        rKonum := MAX(0.0, rKonum - GVL_Ayarlar.rAdim);
    END_IF;

    // Yolun sonuna ulasan ambalaj modelden cikar.
    IF rKonum >= GVL_Ayarlar.rYolSonu THEN
        xAmbalajVar := FALSE;
    END_IF;
END_IF;

// Sensorleri ambalajin gercek model konumundan uret.
stSensor.xGirislerGecerli := TRUE;
stSensor.xYolBos := NOT xAmbalajVar;

stSensor.xGiris := xAmbalajVar AND
    (ABS(rKonum - GVL_Ayarlar.rGirisKonumu)
    <= GVL_Ayarlar.rSensorYaricap);

stSensor.xTanima := xAmbalajVar AND
    (ABS(rKonum - GVL_Ayarlar.rTanimaKonumu)
    <= GVL_Ayarlar.rSensorYaricap);

stSensor.xKabulNoktasi := xAmbalajVar AND
    (ABS(rKonum - GVL_Ayarlar.rKabulKonumu)
    <= GVL_Ayarlar.rSensorYaricap);

stSensor.xIade := xAmbalajVar AND
    (rKonum <= GVL_Ayarlar.rIadeSiniri);

