    xYonCakismasi    : BOOL;
    xIsteklerBos     : BOOL;
END_VAR
VAR_OUTPUT
    eDurum       : E_CalismaDurumu := E_CalismaDurumu.DURDU;
    uiDurum      : UINT;
    xCalismaIzni : BOOL;
    xHata        : BOOL;
END_VAR
VAR
    fbBaslat    : R_TRIG;
    fbSifirla   : R_TRIG;
    xIlkCevrim  : BOOL := TRUE;
END_VAR

FUNCTION_BLOCK FB_CalismaYonetimi
VAR_INPUT
    xBaslat          : BOOL;
    xDurdur          : BOOL;
    xSifirla         : BOOL;
    xGirislerGecerli  : BOOL;
    xYonCakismasi    : BOOL;
    xIsteklerBos     : BOOL;
END_VAR
VAR_OUTPUT
    eDurum       : E_CalismaDurumu := E_CalismaDurumu.DURDU;
    uiDurum      : UINT;
    xCalismaIzni : BOOL;
    xHata        : BOOL;
END_VAR
VAR
    fbBaslat    : R_TRIG;
    fbSifirla   : R_TRIG;
    xIlkCevrim  : BOOL := TRUE;
END_VAR

FUNCTION_BLOCK FB_CalismaYonetimi
VAR_INPUT
    xBaslat          : BOOL;
    xDurdur          : BOOL;
    xSifirla         : BOOL;
    xGirislerGecerli  : BOOL;
    xYonCakismasi    : BOOL;
    xIsteklerBos     : BOOL;
END_VAR
VAR_OUTPUT
    eDurum       : E_CalismaDurumu := E_CalismaDurumu.DURDU;
    uiDurum      : UINT;
    xCalismaIzni : BOOL;
    xHata        : BOOL;
END_VAR
VAR
    fbBaslat    : R_TRIG;
    fbSifirla   : R_TRIG;
    xIlkCevrim  : BOOL := TRUE;
END_VAR

ST.xhtml:
fbBaslat(CLK := xBaslat);
fbSifirla(CLK := xSifirla);

IF xIlkCevrim THEN
    xIlkCevrim := FALSE;
    eDurum := E_CalismaDurumu.DURDU;
ELSIF NOT xGirislerGecerli OR xYonCakismasi THEN
    eDurum := E_CalismaDurumu.HATA;
ELSE
    CASE eDurum OF
        E_CalismaDurumu.DURDU:
            IF fbBaslat.Q AND xIsteklerBos
               AND NOT xDurdur AND NOT xSifirla THEN
                eDurum := E_CalismaDurumu.HAZIR;
            END_IF;

        E_CalismaDurumu.HAZIR:
            IF xDurdur OR xSifirla THEN
                eDurum := E_CalismaDurumu.DURDU;
            END_IF;

        E_CalismaDurumu.HATA:
            IF fbSifirla.Q AND xIsteklerBos AND NOT xBaslat THEN
                eDurum := E_CalismaDurumu.DURDU;
            END_IF;

        ELSE
            eDurum := E_CalismaDurumu.HATA;
    END_CASE;
END_IF;

xCalismaIzni := eDurum = E_CalismaDurumu.HAZIR;
xHata := eDurum = E_CalismaDurumu.HATA;
uiDurum := TO_UINT(eDurum);

